333				behaviorDigest: REACT_MEMOS_PROJECTION_BEHAVIOR_DIGEST,
334				seedSha256,
335				seedFixture: REACT_MEMOS_PROJECTION_SEED_FIXTURE,
336				amendment: REACT_MEMOS_SEED_AMENDMENT,
337			},
338			runs,
339			mutation,
340			consoleErrors: WITNESS_REACT_MEMOS_CONSOLE_ERRORS,
341			failedRequests: WITNESS_REACT_MEMOS_FAILED_REQUESTS,
342			renderedStyleParity: {
343				state: 'measured-identical-resolved-styles',
344				probes: WITNESS_REACT_MEMOS_STYLE_PROBES.length,
345				lanesAgree: true,
346				note: 'the baseline ships the stylesheet Vite 2.9.5 emitted and the migrated lane ships the one Vite 8.0.16 emitted, 2454 bytes smaller and differently named, and the two still resolve to identical appearance at every probe',
347			},
348			scrollAbsence: runs[0]!.scrollAbsence,
349			router: {
350				library: 'application-authored-pathname-switch',
351				routes: [...WITNESS_REACT_MEMOS_ROUTER_ROUTES],
352				fallback: '*',
353				navigations: runs[0]!.routes.length,
354			},
355			readiness: {
356				reactLineage: { ready: 1, total: 4, counted: false },
357				overall: { ready: 3, total: 12 },
358			},
359			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
360			nonclaims: [
361				'This is one React lineage under direct Witness and does not establish generic React, generic Vite, or generic old-Vite-to-Vite-8 support.',
362				'The React lineage readiness score is unchanged at 1/4; this vertical is not counted before Judge audit.',
363				"The API this journey talks to is a frozen synthetic loopback projection authored for this fixture, not the repository's Go backend. No captured production payload, no real account and no real user data are involved, and nothing here is evidence about that backend.",
364				"The seeded owner credentials were amended after the projection was frozen, because the pinned application's own client-side validator refused the original pair. The superseded seed digest and behaviour digest are recorded in this receipt; nothing but the owner pair moved.",
365				"The baseline lane was NOT built with the repository's declared build command: `tsc && vite build` fails in its tsc gate at this revision, so the era lane ran `vite build` alone. Every baseline claim here stands on that deviated command.",
366				'Scroll is not tested. Every stage the journey occupies was measured at 1280x720 and none of them overflows the document, because the application pins its page wrapper to the viewport and scrolls its own panels; no scroll coverage is claimed.',
367				'Drag is not tested because the visited routes have no genuine drag surface.',
368				'`POST /api/resource` is enumerated in the pinned client and deliberately not projected, so no claim is made about file upload or about the `/h/r/:id/:filename` byte stream behind it.',
369				'The application’s own cypress or unit suites were not run; this is a browser proof of the journeys named above, not a substitute for the upstream suite.',
370				'Locality is process-scoped and does not establish operating-system-wide isolation.',
371				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
372			],
373			integrity: { algorithm: 'sha256', canonicalDigest: '' },
374		};
375		receipt.integrity.canonicalDigest = witnessReactMemosDigest(receipt);
376		parseWitnessReactMemosReceipt(receipt);
377		await mkdir(witnessEvidence, { recursive: true });
378		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
379			flag: 'wx',
380		});
381		await writeFile(join(witnessEvidence, 'receipt.md'), renderWitnessReactMemosReceipt(receipt), {
382			flag: 'wx',
383		});
384		return receipt;
385	}
386	
387	export async function verifyWitnessReactMemos(
388		output = witnessEvidence,
389	): Promise<WitnessReactMemosReceipt> {
390		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
391		const receipt = parseWitnessReactMemosReceipt(
392			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
393		);
394		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
395			throw new Error('Memos linked Witness provenance differs');
396		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
397		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
398			throw new Error('Memos build-lane receipt bytes drifted');
399		if (
400			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
401			renderWitnessReactMemosReceipt(receipt)
402		)
403			throw new Error('Memos human Witness receipt differs');
404		const serialized = canonicalize(receipt);
405		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
406			throw new Error('Memos receipt leaks host identity');
407		return receipt;
408	}
409	
410	export async function main(args = process.argv.slice(2)): Promise<void> {
411		const publishIndex = args.indexOf('--publish');
412		const verifyIndex = args.indexOf('--verify');
413		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
414			const output = resolve(root, args[publishIndex + 1]!);
415			if (output !== witnessEvidence) throw new Error('Memos publish path differs');
416			const receipt = await runWitnessReactMemos();
417			process.stdout.write(
418				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
419			);
420			return;
421		}
422		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
423			const receipt = await verifyWitnessReactMemos(resolve(root, args[verifyIndex + 1]!));
424			process.stdout.write(
425				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
426			);
427			return;
428		}
429		throw new Error('Memos Witness runner requires --run-twice --publish <dir> or --verify <dir>');
430	}
431	
432	if (basename(process.argv[1] ?? '') === 'react-memos-run.ts')
433		main().catch((error: unknown) => {
434			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
435			process.exitCode = 1;
436		});
