			? {}
			: {
					serviceWorker: buildRealServiceWorkerEvidence({
						...completedJourney.realServiceWorker,
						before: beforeInventory.entries,
						after: afterInventory.entries,
						workerEvents: observerFinalization.workerEvents,
					}),
				}),
