import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { join, extname } from 'node:path';
import { chromium } from 'playwright';

const lane = process.argv[2] ?? 'migrated';
const roots = {
	baseline:
		'/Users/jacksm5pro/dev/open-source/versionless/.versionless/work/angular-eshop-webspa/build-run1',
	migrated:
		'/Users/jacksm5pro/dev/open-source/versionless/.versionless/work/angular-eshop-webspa/target/app/wwwroot',
};
const root = roots[lane];

const BRANDS = [
	{ id: 1, brand: 'Azure' },
	{ id: 2, brand: '.NET' },
	{ id: 3, brand: 'Visual Studio' },
	{ id: 4, brand: 'SQL Server' },
	{ id: 5, brand: 'Other' },
];
const TYPES = [
	{ id: 1, type: 'Mug' },
	{ id: 2, type: 'T-Shirt' },
	{ id: 3, type: 'Sheet' },
	{ id: 4, type: 'USB Memory Stick' },
];
const ITEMS = [];
let id = 1;
for (const b of BRANDS)
	for (const t of TYPES) {
		ITEMS.push({
			id: String(id),
			name: `${b.brand} ${t.type}`,
			description: `${b.brand} ${t.type} description`,
			price: 10 + id,
			pictureUri: 'assets/images/brand.png',
			catalogBrandId: b.id,
			catalogBrand: b.brand,
			catalogTypeId: t.id,
			catalogType: t.type,
			units: 0,
		});
		id += 1;
	}

const CONFIG = {
	identityUrl: '',
	marketingUrl: '',
	purchaseUrl: '',
	signalrHubUrl: '',
	activateCampaignDetailFunction: false,
};

const MIME = {
	'.html': 'text/html',
	'.js': 'text/javascript',
	'.css': 'text/css',
	'.png': 'image/png',
	'.svg': 'image/svg+xml',
	'.ico': 'image/x-icon',
	'.woff': 'font/woff',
	'.ttf': 'font/ttf',
	'.eot': 'application/vnd.ms-fontobject',
	'.txt': 'text/plain',
};

const apiLog = [];

function page_(items, pageIndex, pageSize) {
	const start = pageIndex * pageSize;
	return {
		pageIndex,
		pageSize,
		count: items.length,
		data: items.slice(start, start + pageSize),
	};
}

function api(method, pathname, search) {
	const q = new URLSearchParams(search);
	const pageIndex = Number(q.get('pageIndex') ?? '0');
	const pageSize = Number(q.get('pageSize') ?? '10');
	if (pathname === '/Home/Configuration') return CONFIG;
	if (pathname === '/api/v1/c/catalog/catalogbrands') return BRANDS;
	if (pathname === '/api/v1/c/catalog/catalogtypes') return TYPES;
	if (pathname === '/api/v1/c/catalog/items') return page_(ITEMS, pageIndex, pageSize);
	const m = pathname.match(/^\/api\/v1\/c\/catalog\/items\/type\/([^/]*)\/brand\/([^/]*)$/);
	if (m) {
		const type = m[1];
		const brand = m[2];
		let filtered = ITEMS;
		if (type !== 'all' && type !== '') filtered = filtered.filter((i) => String(i.catalogTypeId) === type);
		if (brand !== 'all' && brand !== '') filtered = filtered.filter((i) => String(i.catalogBrandId) === brand);
		return page_(filtered, pageIndex, pageSize);
	}
	return undefined;
}

const server = createServer((req, res) => {
	void (async () => {
		const url = new URL(req.url ?? '/', 'http://127.0.0.1');
		const answered = api(req.method ?? 'GET', url.pathname, url.search.replace(/^\?/, ''));
		if (answered !== undefined) {
			apiLog.push({ method: req.method, path: url.pathname, search: url.search });
			const body = Buffer.from(JSON.stringify(answered));
			res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' });
			res.end(body);
			return;
		}
		if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/Home/')) {
			apiLog.push({ method: req.method, path: url.pathname, search: url.search, refused: true });
			res.writeHead(404, { 'content-type': 'text/plain' });
			res.end('refused');
			return;
		}
		let file = join(root, url.pathname === '/' ? 'index.html' : url.pathname.slice(1));
		let ok = await stat(file).then((s) => s.isFile(), () => false);
		if (!ok && !extname(url.pathname)) {
			file = join(root, 'index.html');
			ok = true;
		}
		if (!ok) {
			res.writeHead(404, { 'content-type': 'text/plain' });
			res.end('not found');
			return;
		}
		const body = await readFile(file);
		res.writeHead(200, {
			'content-type': MIME[extname(file)] ?? 'application/octet-stream',
			'cache-control': 'no-store',
		});
		res.end(body);
	})();
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const port = server.address().port;
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await ctx.newPage();
const consoleMsgs = [];
const failed = [];
page.on('console', (m) => consoleMsgs.push(`${m.type()}: ${m.text()}`));
page.on('pageerror', (e) => consoleMsgs.push(`pageerror: ${e.message}`));
page.on('requestfailed', (r) => failed.push(`${r.url()} ${r.failure()?.errorText}`));

await page.goto(origin, { waitUntil: 'load' });
await page.waitForSelector('.esh-catalog-item', { timeout: 15000 }).catch(() => {});
await page.waitForTimeout(600);

const dump = async (label) => {
	const out = await page.evaluate(() => {
		const sel = (s) => [...document.querySelectorAll(s)];
		return {
			items: sel('.esh-catalog-item').length,
			names: sel('.esh-catalog-name span').map((e) => e.textContent.trim()),
			prices: sel('.esh-catalog-price span').map((e) => e.textContent.trim()),
			brandOptions: sel('.esh-catalog-label[data-title=brand] option').map((e) => [
				e.value,
				e.textContent.trim(),
			]),
			typeOptions: sel('.esh-catalog-label[data-title=type] option').map((e) => [
				e.value,
				e.textContent.trim(),
			]),
			pagerText: sel('.esh-pager-item')
				.map((e) => e.textContent.trim())
				.filter((t) => t.startsWith('Showing')),
			pagers: sel('.esh-pager').length,
			nextDisabled: sel('#Next').map((e) => e.className),
			prevDisabled: sel('#Previous').map((e) => e.className),
			identity: sel('.esh-identity-name').map((e) => e.textContent.trim()),
			basketStatus: sel('esh-basket-status').length,
			thumbs: sel('.esh-catalog-thumbnail').map((e) => e.getAttribute('src')),
			title: document.title,
			bodyHas: document.body.innerText.slice(0, 400),
		};
	});
	console.log(`\n=== ${label} ===`);
	console.log(JSON.stringify(out, null, 1));
	return out;
};

await dump('initial');

// brand filter via keyboard on the native select
await page.focus('.esh-catalog-label[data-title=brand] .esh-catalog-filter');
await page.press('.esh-catalog-label[data-title=brand] .esh-catalog-filter', 'ArrowDown');
await page.waitForTimeout(200);
const brandVal = await page.$eval(
	'.esh-catalog-label[data-title=brand] .esh-catalog-filter',
	(e) => e.value,
);
console.log('\nbrand select value after ArrowDown:', brandVal);
await page.click('.esh-catalog-send');
await page.waitForTimeout(800);
await dump('after brand filter');

// pager next
await page.click('#Next');
await page.waitForTimeout(800);
await dump('after next');

console.log('\n=== api log ===');
console.log(JSON.stringify(apiLog, null, 1));
console.log('\n=== console ===');
console.log(consoleMsgs.join('\n'));
console.log('\n=== failed requests ===');
console.log(failed.join('\n'));

await browser.close();
server.close();

